export function answerSchema(question) {
  let suggestions = specific[question.id];
  if (!suggestions) {
    const text = question.text;
    if (/你(?:会|能|可以|是否)?.*(?:接受|介意|在意|认同)|你相信|你觉得.*(?:吗|么)[？?]?$/.test(text)) {
      suggestions = /介意|在意/.test(text) ? ['会比较在意', '不太在意', '需要看具体情况'] : ['倾向于会／可以', '倾向于不会／不可以', '要看具体情况，还想聊聊'];
    } else if (/有没有|是否有|有过.*[？?]$/.test(text)) {
      suggestions = [say('有，想说说自己的经历'), '暂时没有想到'];
    }
  }
  const options = (suggestions ?? []).map((item, index) => typeof item === 'string'
    ? { id: `c${index}`, label: item, requiresText: false }
    : { id: `c${index}`, ...item });
  options.push({ id: 'custom', label: '我想自己说', requiresText: true });
  return { version: 1, options, customOnly: options.length === 1, maxTextLength: 500 };
}

export function normalizeAnswer(question, input) {
  const schema = answerSchema(question);
  if (!input || typeof input !== 'object') throw new Error('请先选择一个答案，或写下自己的想法。');
  const option = schema.options.find(option => option.id === input.choiceId);
  if (!option) throw new Error('这个选项不在当前题目中，请重新选择。');
  const note = typeof input.text === 'string' ? input.text.trim() : '';
  if (note.length > schema.maxTextLength) throw new Error('补充文字请控制在 500 字以内。');
  if (option.requiresText && !note) throw new Error('请写一点自己的想法，再提交这一题。');
  return { choiceId: option.id, label: option.label, text: note };
}
